/**
 * iOS implementation of the runtime abstraction the generated Godot API wrappers call (mirrors the
 * desktop `ObjectCalls`). Every helper routes through the single generic C dispatch
 * `kanama_ios_godot_ptrcall`; Kotlin lays out the POD/struct/object arg bytes here, the C side
 * passes them straight to `object_method_bind_ptrcall`.
 *
 * Marshalling rules (see docs/contributing/backends/ios.md):
 * - SCALAR `float` args/returns are 8-byte `double` at ptrcall (PtrToArg<float> =
 *   convert<float,double>) — so a Godot `float` scalar uses the `*Double*` helpers.
 * - Vector COMPONENTS are real_t (4-byte float32 in single-precision builds); they marshal through
 *   [GodotReal]/[GodotRealVar] so a precision switch stays centralized. Color components are always
 *   float32 (never real_t) and stay raw FloatVar.
 */
actual object ObjectCalls {
  // The ptrcall type tags (PT_*) are declared ONCE, in the GENERATED MEMBERS region at the end of
  // this object: the generator owns the whole table (it must match the KANAMA_IOS_PT_* enum in
  // kanama_ios_shim.c) and the hand-written helpers below read the very same constants. Before
  // task 104 step 3 parcel B the table existed twice -- here and in the deleted
  // ObjectCallsGenerated.kt.
  // Blob kinds of kanama_ios_godot_ptrcall_ret_array_blob (KANAMA_IOS_BLOB_* in the C shim).
  private const val BLOB_PACKED_STRING_ARRAY = 1
  private const val BLOB_TYPED_ARRAY = 2

  // Godot Variant type tags (returned by kanama_ios_godot_object_call, for decoding
  // a scalar return). Must match the KANAMA_IOS_VARIANT_TYPE_* enum in the C shim.
  private const val VT_BOOL = 1
  // Packed*Array Variant types (KANAMA_IOS_VARIANT_TYPE_PACKED_* in the C shim), the kind selector
  // of kanama_ios_godot_ptrcall_ret_packed (task 100, parcel 3).
  internal const val VT_PACKED_BYTE_ARRAY = 29
  internal const val VT_PACKED_INT32_ARRAY = 30
  internal const val VT_PACKED_INT64_ARRAY = 31
  internal const val VT_PACKED_FLOAT32_ARRAY = 32
  internal const val VT_PACKED_FLOAT64_ARRAY = 33
  internal const val VT_PACKED_VECTOR2_ARRAY = 35
  internal const val VT_PACKED_VECTOR3_ARRAY = 36
  internal const val VT_PACKED_COLOR_ARRAY = 37
  // Variant.Type ids array_set_typed takes for typed-Array ARGUMENTS (task 100, parcel 8); VT_INT
  // (2) is the existing constant below.
  internal const val VT_STRING_TYPE = 4
  internal const val VT_VECTOR2I_TYPE = 6
  internal const val VT_PLANE_TYPE = 14
  internal const val VT_TRANSFORM3D_TYPE = 18
  internal const val VT_STRING_NAME_TYPE = 21
  internal const val VT_NODE_PATH_TYPE = 22
  internal const val VT_RID_TYPE = 23
  internal const val VT_OBJECT_TYPE = 24
  // Variant.Type NIL: the descriptor asks for an UNTYPED Array (array_set_typed is skipped).
  internal const val VT_NIL_TYPE = 0
  internal const val VT_PACKED_VECTOR2_ARRAY_TYPE = 35
  internal const val VT_PACKED_STRING_ARRAY_TYPE = 34
  private const val VT_INT = 2
  private const val VT_FLOAT = 3
  private const val VT_STRING = 4
  private const val VT_VECTOR2 = 5
  private const val VT_VECTOR2I = 6
  private const val VT_VECTOR3 = 9
  private const val VT_COLOR = 20
  private const val VT_STRING_NAME = 21
  private const val VT_NODE_PATH = 22
  private const val VT_OBJECT = 24
  private const val VT_DICTIONARY = 27
  private const val VT_ARRAY = 28

  actual fun constructObject(className: String): MemorySegment =
    MemorySegment.ofAddress(kanama_ios_godot_construct_object(className))

  actual fun getMethodBind(className: String, methodName: String, hash: Long): MemorySegment =
    MemorySegment.ofAddress(kanama_ios_godot_get_method_bind(className, methodName, hash))

  // Resolve a Godot engine singleton (Input, Engine, …). Mirrors desktop ObjectCalls;
  // used by the bespoke Input glue (and generated singleton wrappers, longer term).
  actual fun getSingleton(name: String): MemorySegment =
    MemorySegment.ofAddress(kanama_ios_godot_get_singleton(name))

  // Destroy an engine Object immediately (GDExtension object_destroy). Mirrors desktop
  // ObjectCalls.destroyObject; RefCounted.close()/releaseHandle call it only after
  // unreference() returned true (refcount hit zero) — task 31 ownership mirror.
  fun destroyObject(instance: MemorySegment) {
    if (instance.address() == 0L) return
    kanama_ios_godot_object_destroy(instance.address())
  }

  // ---- no-arg ----
  actual fun ptrcallNoArgs(methodBind: MemorySegment, instance: MemorySegment) {
    kanama_ios_godot_ptrcall(methodBind.address(), instance.address(), null, null, 0, PT_VOID, null)
  }

  actual fun ptrcallNoArgsRetBool(methodBind: MemorySegment, instance: MemorySegment): Boolean =
    memScoped {
      val ret = alloc<ByteVar>()
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_BOOL,
        ret.ptr,
      )
      ret.value.toInt() != 0
    }

  // All Godot scalar ints are 8 bytes (int64) at ptrcall (PtrToArg<int32_t> =
  // convert<int32_t,int64_t>), so int returns read 8 bytes then narrow.
  actual fun ptrcallNoArgsRetInt(methodBind: MemorySegment, instance: MemorySegment): Int =
    memScoped {
      val ret = alloc<LongVar>()
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_INT64,
        ret.ptr,
      )
      ret.value.toInt()
    }

  // RefCounted lifetime binds for the issue #81 save guard below. reference()/unreference() share
  // the bool() no-arg hash; get_reference_count() is int().
  private val refCountedReferenceBind by lazy {
    getMethodBind("RefCounted", "reference", 2240911060L)
  }
  private val refCountedUnreferenceBind by lazy {
    getMethodBind("RefCounted", "unreference", 2240911060L)
  }
  private val refCountedGetReferenceCountBind by lazy {
    getMethodBind("RefCounted", "get_reference_count", 3905245786L)
  }

  // issue #81 — hand-written (IOS_HANDWRITTEN_HELPERS) mirror of the desktop guard. This shape
  // backs
  // ResourceSaver.save — its sole wrapper. save decodes its `const Ref<Resource>&` argument into a
  // transient Ref and releases it on return. For a freshly created,
  // not-yet-assigned resource — whose only reference is Godot's construction placeholder — that
  // release drops the refcount to zero and frees the object, dangling its Kotlin wrapper. Hold a
  // protective reference across the call, then release it only if the object still has another
  // holder:
  // when the call consumed the sole reference the ref is kept (the resource becomes wrapper-owned,
  // close() frees it); for an already-owned resource it is a balanced no-op.
  actual fun ptrcallWithObjectStringLongArgsRetLong(
    methodBind: MemorySegment,
    instance: MemorySegment,
    objectArg: MemorySegment,
    text: String,
    value: Long,
  ): Long {
    val guardHandle = objectArg.address() != 0L
    if (guardHandle) ptrcallNoArgsRetBool(refCountedReferenceBind, objectArg)
    try {
      return memScoped {
        val ret = alloc<LongVar>()
        val c0 = alloc<LongVar>()
        c0.value = objectArg.address()
        val c2 = alloc<LongVar>()
        c2.value = value
        val types = allocArray<IntVar>(3)
        types[0] = PT_OBJECT
        types[1] = PT_STRING
        types[2] = PT_INT64
        val ptrs = allocArray<COpaquePointerVar>(3)
        ptrs[0] = c0.ptr.reinterpret<CPointed>()
        ptrs[1] = text.cstr.ptr.reinterpret<CPointed>()
        ptrs[2] = c2.ptr.reinterpret<CPointed>()
        kanama_ios_godot_ptrcall(
          methodBind.address(),
          instance.address(),
          types,
          ptrs,
          3,
          PT_INT64,
          ret.ptr,
        )
        ret.value
      }
    } finally {
      if (guardHandle && ptrcallNoArgsRetInt(refCountedGetReferenceCountBind, objectArg) > 1) {
        ptrcallNoArgsRetBool(refCountedUnreferenceBind, objectArg)
      }
    }
  }

  actual fun ptrcallNoArgsRetLong(methodBind: MemorySegment, instance: MemorySegment): Long =
    memScoped {
      val ret = alloc<LongVar>()
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_INT64,
        ret.ptr,
      )
      ret.value
    }

  actual fun ptrcallNoArgsRetDouble(methodBind: MemorySegment, instance: MemorySegment): Double =
    memScoped {
      val ret = alloc<DoubleVar>()
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_FLOAT64,
        ret.ptr,
      )
      ret.value
    }

  actual fun ptrcallNoArgsRetObject(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): MemorySegment = memScoped {
    val ret = alloc<LongVar>()
    ret.value = 0
    kanama_ios_godot_ptrcall(
      methodBind.address(),
      instance.address(),
      null,
      null,
      0,
      PT_OBJECT,
      ret.ptr,
    )
    MemorySegment.ofAddress(ret.value)
  }

  actual fun ptrcallNoArgsRetVector2(methodBind: MemorySegment, instance: MemorySegment): Vector2 =
    memScoped {
      val ret = allocArray<GodotRealVar>(2)
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_VECTOR2,
        ret,
      )
      Vector2(GodotReal.fromC(ret[0]), GodotReal.fromC(ret[1]))
    }

  actual fun ptrcallNoArgsRetVector3(methodBind: MemorySegment, instance: MemorySegment): Vector3 =
    memScoped {
      val ret = allocArray<GodotRealVar>(3)
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_VECTOR3,
        ret,
      )
      Vector3(GodotReal.fromC(ret[0]), GodotReal.fromC(ret[1]), GodotReal.fromC(ret[2]))
    }

  // Vector2i (2x int32, 8 bytes total): components are int32 NOT widened — struct
  // uses PtrToArgDirect/PtrToArgByReference, not PtrToArgConvert.
  actual fun ptrcallNoArgsRetVector2i(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): Vector2i = memScoped {
    val ret = allocArray<IntVar>(2)
    kanama_ios_godot_ptrcall(
      methodBind.address(),
      instance.address(),
      null,
      null,
      0,
      PT_VECTOR2I,
      ret,
    )
    Vector2i(ret[0], ret[1])
  }

  // Vector3i (3x int32, 12 bytes total): components are int32 NOT widened.
  actual fun ptrcallNoArgsRetVector3i(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): Vector3i = memScoped {
    val ret = allocArray<IntVar>(3)
    kanama_ios_godot_ptrcall(
      methodBind.address(),
      instance.address(),
      null,
      null,
      0,
      PT_VECTOR3I,
      ret,
    )
    Vector3i(ret[0], ret[1], ret[2])
  }

  // Color (4x float32, 16 bytes): components are always float32 (not real_t, not double).
  // No widening: PtrToArgDirect<Color> lays 4×float32 raw.
  actual fun ptrcallNoArgsRetColor(methodBind: MemorySegment, instance: MemorySegment): Color =
    memScoped {
      val ret = allocArray<FloatVar>(4)
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_COLOR,
        ret,
      )
      Color(ret[0], ret[1], ret[2], ret[3])
    }

  // Rect2 (4x float32, 16 bytes): position.x, position.y, size.x, size.y.
  // Components are real_t = float32 on single-precision iOS (same convention as Vector2).
  actual fun ptrcallNoArgsRetRect2(methodBind: MemorySegment, instance: MemorySegment): Rect2 =
    memScoped {
      val ret = allocArray<GodotRealVar>(4)
      kanama_ios_godot_ptrcall(
        methodBind.address(),
        instance.address(),
        null,
        null,
        0,
        PT_RECT2,
        ret,
      )
      Rect2(
        Vector2(GodotReal.fromC(ret[0]), GodotReal.fromC(ret[1])),
        Vector2(GodotReal.fromC(ret[2]), GodotReal.fromC(ret[3])),
      )
    }

  // String return: a Godot String can't ride the fixed ret_out of the generic
  // dispatch, so it routes through the dedicated C helper. Two-call protocol —
  // measure the UTF-8 byte length (NULL buffer), then allocate and fill. Safe to
  // call twice because the wired methods are pure getters. string_to_utf8_chars
  // writes no null terminator, so decode exactly `len` bytes.
  actual fun ptrcallNoArgsRetString(methodBind: MemorySegment, instance: MemorySegment): String =
    memScoped {
      val len =
        kanama_ios_godot_ptrcall_no_args_ret_string(
          methodBind.address(),
          instance.address(),
          null,
          0L,
        )
      if (len <= 0L) {
        ""
      } else {
        val buf = allocArray<ByteVar>(len)
        kanama_ios_godot_ptrcall_no_args_ret_string(
          methodBind.address(),
          instance.address(),
          buf,
          len,
        )
        buf.readBytes(len.toInt()).decodeToString()
      }
    }

  // StringName return: GDExtension has no StringName->utf8, so the dedicated C helper
  // converts the returned StringName to a String (String(from: StringName) ctor) and
  // UTF-8 encodes it. Same two-call length protocol as ptrcallNoArgsRetString.
  actual fun ptrcallNoArgsRetStringName(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): String = memScoped {
    val len =
      kanama_ios_godot_ptrcall_no_args_ret_string_name(
        methodBind.address(),
        instance.address(),
        null,
        0L,
      )
    if (len <= 0L) {
      ""
    } else {
      val buf = allocArray<ByteVar>(len)
      kanama_ios_godot_ptrcall_no_args_ret_string_name(
        methodBind.address(),
        instance.address(),
        buf,
        len,
      )
      buf.readBytes(len.toInt()).decodeToString()
    }
  }

  // task 100 (parcel 1) — String / StringName / NodePath return on any audited arg shape. The
  // generated helpers lay out their arg cells exactly as for kanama_ios_godot_ptrcall and hand
  // them here with the return builtin's tag (PT_STRING / PT_STRING_NAME / PT_NODE_PATH). The C
  // entry runs the method ONCE and UTF-8 encodes the return: it fits the inline buffer in the
  // common case; a longer value is parked C-side and drained in full by the second call, so
  // nothing is truncated (unlike the 1 KiB Object-call decode) and nothing is re-issued (unlike
  // the no-arg helpers' two-call length protocol, which is only safe for pure getters).
  fun ptrcallRetUtf8(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
    retTag: Int,
  ): String = memScoped {
    val inlineCap = 1024L
    val inline = allocArray<ByteVar>(inlineCap)
    val len =
      kanama_ios_godot_ptrcall_ret_utf8(
        methodBind.address(),
        instance.address(),
        argTypes,
        argPtrs,
        argCount,
        retTag,
        inline,
        inlineCap,
      )
    when {
      len <= 0L -> ""
      len <= inlineCap -> inline.readBytes(len.toInt()).decodeToString()
      else -> {
        val full = allocArray<ByteVar>(len)
        val got = kanama_ios_godot_take_pending_utf8(full, len)
        if (got <= 0L) "" else full.readBytes(minOf(got, len).toInt()).decodeToString()
      }
    }
  }

  // task 100 (parcel 11) — Callable RETURN on any audited arg shape. Same arg cells as
  // kanama_ios_godot_ptrcall; the C entry runs the method ONCE into a Callable cell, reads the
  // target Object pointer and the method name back through Callable.get_object / get_method
  // (exactly what desktop's BuiltinTypes.readCallable does), and UTF-8 encodes the name like
  // ptrcallRetUtf8 (inline buffer, pending slot beyond it). An empty Callable is null, as on
  // desktop; the target is a borrowed GodotObject over the raw handle, like every Object return.
  fun ptrcallRetCallable(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): GodotCallable? = memScoped {
    val inlineCap = 256L
    val inline = allocArray<ByteVar>(inlineCap)
    val handle = alloc<LongVar>()
    handle.value = 0L
    val len =
      kanama_ios_godot_ptrcall_ret_callable(
        methodBind.address(),
        instance.address(),
        argTypes,
        argPtrs,
        argCount,
        handle.ptr,
        inline,
        inlineCap,
      )
    if (len < 0L || handle.value == 0L) return@memScoped null
    val method =
      when {
        len == 0L -> ""
        len <= inlineCap -> inline.readBytes(len.toInt()).decodeToString()
        else -> {
          val full = allocArray<ByteVar>(len)
          val got = kanama_ios_godot_take_pending_utf8(full, len)
          if (got <= 0L) "" else full.readBytes(minOf(got, len).toInt()).decodeToString()
        }
      }
    GodotCallable(GodotObject(handle.value), method)
  }

  // task 100 (parcel 2) — Variant-scalar return on any audited arg shape. Same arg cells as
  // kanama_ios_godot_ptrcall; the C entry ptrcalls into a Variant cell and decodes the scalar
  // payload exactly like the Object-call path (borrowed Object decode, like desktop's
  // RetVariantScalar). Long String-family payloads come back whole through the pending slot.
  fun ptrcallRetVariantScalar(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): Any? = memScoped {
    val outInt = alloc<LongVar>()
    val outDouble = alloc<DoubleVar>()
    val strBufSize = 1024L
    val outStr = allocArray<ByteVar>(strBufSize)
    val outStrLen = alloc<LongVar>()
    val retType =
      kanama_ios_godot_ptrcall_ret_variant_scalar(
        methodBind.address(),
        instance.address(),
        argTypes,
        argPtrs,
        argCount,
        outInt.ptr,
        outDouble.ptr,
        outStr,
        strBufSize,
        outStrLen.ptr,
      )
    decodeVariantScalarReturn(retType, outInt, outDouble, outStr, strBufSize, outStrLen, null)
  }

  // task 100 (parcel 3) — Packed*Array returns on any audited arg shape. Same arg cells as
  // kanama_ios_godot_ptrcall; the C entry ptrcalls into a packed-array cell, reads the element
  // count and copies the contiguous elements out in ONE memcpy (the Android ART lesson applied
  // C-side). An array longer than the inline capacity is parked C-side and drained whole by the
  // second call, so the method runs once and nothing is truncated. The kind selects the element
  // layout: byte 1, int32 4, int64 8, float32 4, float64 8, Vector2 2×real, Vector3 3×real,
  // Color 4×float32 — the same encodings the no-arg read-backs use.
  private fun MemScope.ptrcallPackedElements(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
    packedKind: Int,
    elemBytes: Int,
  ): Pair<CPointer<ByteVar>, Int> {
    val inlineCap = 256L
    val inline = allocArray<ByteVar>(inlineCap * elemBytes)
    val count =
      kanama_ios_godot_ptrcall_ret_packed(
        methodBind.address(),
        instance.address(),
        argTypes,
        argPtrs,
        argCount,
        packedKind,
        inline,
        inlineCap,
      )
    return when {
      count <= 0L -> Pair(inline, 0)
      count <= inlineCap -> Pair(inline, count.toInt())
      else -> {
        val full = allocArray<ByteVar>(count * elemBytes)
        val got = kanama_ios_godot_take_pending_packed(packedKind, full, count)
        Pair(full, if (got <= 0L) 0 else minOf(got, count).toInt())
      }
    }
  }

  fun ptrcallRetByteArray(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): ByteArray = memScoped {
    val (buf, n) =
      ptrcallPackedElements(
        methodBind,
        instance,
        argTypes,
        argPtrs,
        argCount,
        VT_PACKED_BYTE_ARRAY,
        1,
      )
    if (n == 0) ByteArray(0) else buf.readBytes(n)
  }

