  ): Map<String, Any?> = memScoped {
    val bytes =
      ptrcallContainerBlob(methodBind, instance, argTypes, argPtrs, argCount, VT_DICTIONARY)
    if (bytes.size < 4) emptyMap() else ContainerBlob(bytes, 0).dictionary()
  }

  fun ptrcallRetArray(
