  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_TRANSFORM3D_TYPE,
      null,
      values.map { t ->
        // 9 basis components column-major (ios_arg_layout's Transform3D layout) + 3 origin.
        Pair(
          PT_TRANSFORM3D,
          float32Bytes(
            GodotReal.toC(t.basis.x.x),
            GodotReal.toC(t.basis.y.x),
            GodotReal.toC(t.basis.z.x),
