  // PackedVector2Array return: each element is 2 float32; the C helper fills count*2 floats.
  actual fun ptrcallNoArgsRetPackedVector2List(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<Vector2> = memScoped {
    val count =
      kanama_ios_godot_ptrcall_no_args_ret_packed_vector2_array(
        methodBind.address(),
        instance.address(),
        null,
        0L,
      )
    if (count <= 0L) {
      emptyList()
    } else {
      val buf = allocArray<GodotRealVar>(count * 2)
      kanama_ios_godot_ptrcall_no_args_ret_packed_vector2_array(
        methodBind.address(),
        instance.address(),
        buf,
        count,
      )
      List(count.toInt()) {
        Vector2(GodotReal.fromC(buf[it * 2]), GodotReal.fromC(buf[it * 2 + 1]))
      }
    }
  }

  // PackedColorArray return: each element is 4 float32 (RGBA); the C helper fills count*4 floats.
  actual fun ptrcallNoArgsRetPackedColorList(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<Color> = memScoped {
    val count =
      kanama_ios_godot_ptrcall_no_args_ret_packed_color_array(
        methodBind.address(),
        instance.address(),
        null,
        0L,
      )
    if (count <= 0L) {
      emptyList()
    } else {
      val buf = allocArray<FloatVar>(count * 4)
      kanama_ios_godot_ptrcall_no_args_ret_packed_color_array(
        methodBind.address(),
        instance.address(),
        buf,
        count,
      )
      List(count.toInt()) { Color(buf[it * 4], buf[it * 4 + 1], buf[it * 4 + 2], buf[it * 4 + 3]) }
    }
  }

  // ---- typed-object-array (Array[Object]) returns -> List<T> ----
  // GENERIC over the element wrapper via a `fromHandle: (MemorySegment) -> T?` factory passed by
  // the api-layer caller (e.g. Node::wrap). Keeping the wrapper type out of the helper
  // signature avoids inverting the binding.runtime -> api dependency: the generated wrapper owns
  // its concrete List<Node> return type, the runtime only maps raw handles. The C entry drives a
  // ptrcall whose return is a Godot Array (8-byte opaque), reads each element's object handle via
  // the Array size/get builtins and fills an int64 buffer. task 100 (parcel 9): the method runs
  // ONCE — the handles land in the inline buffer when they fit, otherwise the C side parks them in
  // a pending slot that is drained into a right-sized buffer (the old two-call length protocol
  // re-ran the method, which is only safe for pure getters). Handles are BORROWED, as on desktop
  // (BuiltinTypes.readArrayObjects): the returned Array is destroyed inside the call. Each handle
  // -> MemorySegment -> fromHandle; nulls (non-Object or freed) are dropped. `internal` so the
  // GENERATED helpers (every audited arg shape) share this one body.
  internal inline fun <T> retTypedObjectList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    fromHandle: (MemorySegment) -> T?,
    layoutArgs: MemScope.() -> Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>,
  ): List<T> = memScoped {
    val (types, ptrs, argc) = layoutArgs()
    val inlineBuf = allocArray<LongVar>(TYPED_OBJECT_LIST_INLINE_CAP)
    val count =
      kanama_ios_godot_ptrcall_ret_object_handles(
        methodBind.address(),
        instance.address(),
        types,
        ptrs,
        argc,
        inlineBuf,
        TYPED_OBJECT_LIST_INLINE_CAP.toLong(),
      )
    if (count <= 0L) {
      emptyList()
    } else {
      val buf =
        if (count <= TYPED_OBJECT_LIST_INLINE_CAP) {
          inlineBuf
        } else {
          val parked = allocArray<LongVar>(count)
          kanama_ios_godot_take_pending_object_handles(parked, count)
          parked
        }
      val out = ArrayList<T>(count.toInt())
      for (i in 0 until count.toInt()) {
        val obj = fromHandle(MemorySegment.ofAddress(buf[i]))
        if (obj != null) out.add(obj)
      }
      out
    }
  }

  // Inline handle capacity of retTypedObjectList (longer lists drain from the C pending slot).
  internal const val TYPED_OBJECT_LIST_INLINE_CAP = 64

  // `<T : Any>` is desktop's bound, which an `actual` must repeat (task 104 step 3 parcel C').
  actual fun <T : Any> ptrcallNoArgsRetTypedObjectList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    wrapper: (MemorySegment) -> T?,
  ): List<T> = retTypedObjectList(methodBind, instance, wrapper) { Triple(null, null, 0) }

  fun <T> ptrcallWithBoolArgRetTypedObjectList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    value: Boolean,
    fromHandle: (MemorySegment) -> T?,
  ): List<T> =
    retTypedObjectList(methodBind, instance, fromHandle) {
      val cell = alloc<ByteVar>()
      cell.value = if (value) 1 else 0
      val types = allocArray<IntVar>(1)
      types[0] = PT_BOOL
      val ptrs = allocArray<COpaquePointerVar>(1)
      ptrs[0] = cell.ptr.reinterpret<CPointed>()
      Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>(types, ptrs, 1)
    }

  // (String, String, bool, bool) -> Array[Node] — Node.find_children(pattern, type, recursive,
  // owned).
  // PT_STRING args pass the UTF-8 cstr ptr; the C generic dispatcher constructs (and destroys) the
  // Godot String from it. PT_BOOL args are uint8 cells. Both string cells stay scope-valid across
  // the
  // call because layoutArgs runs once inside retTypedObjectList's memScoped block.
  fun <T> ptrcallWithTwoStringAndTwoBoolArgsRetTypedObjectList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    first: String,
    second: String,
    firstBool: Boolean,
    secondBool: Boolean,
    fromHandle: (MemorySegment) -> T?,
  ): List<T> =
    retTypedObjectList(methodBind, instance, fromHandle) {
      val b0 = alloc<ByteVar>()
      b0.value = if (firstBool) 1 else 0
      val b1 = alloc<ByteVar>()
      b1.value = if (secondBool) 1 else 0
      val types = allocArray<IntVar>(4)
      types[0] = PT_STRING
      types[1] = PT_STRING
      types[2] = PT_BOOL
      types[3] = PT_BOOL
      val ptrs = allocArray<COpaquePointerVar>(4)
      ptrs[0] = first.cstr.ptr.reinterpret<CPointed>()
      ptrs[1] = second.cstr.ptr.reinterpret<CPointed>()
      ptrs[2] = b0.ptr.reinterpret<CPointed>()
      ptrs[3] = b1.ptr.reinterpret<CPointed>()
      Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>(types, ptrs, 4)
    }

