  // PhysicsDirectSpaceState3D.intersect_ray: (query object arg) -> the result Dictionary decoded
  // into a Map. Empty map = no hit. "collider" is a raw object handle (MemorySegment; 0 dropped) —
  // the api layer wraps it as GodotObject. "position"/"normal" are Vector3; "collider_id"/"shape"
  // Long.
  fun ptrcallIntersectRay(
    methodBind: MemorySegment,
    instance: MemorySegment,
    query: MemorySegment,
  ): Map<String, Any?> = memScoped {
    val cells = allocArray<LongVar>(1)
    cells[0] = query.address()
    val types = allocArray<IntVar>(1)
    types[0] = PT_OBJECT
    val ptrs = allocArray<COpaquePointerVar>(1)
    ptrs[0] = cells.reinterpret<CPointed>()
    val buf = allocArray<ByteVar>(64)
    val total =
      kanama_ios_godot_ptrcall_ret_raycast_dict(
        methodBind.address(),
        instance.address(),
        types,
        ptrs,
        1,
        buf,
        64L,
      )
    if (total < 52L) {
      emptyMap()
    } else {
      val bytes = buf.readBytes(total.toInt())
      fun i32(o: Int): Int =
        (bytes[o].toInt() and 0xFF) or
          ((bytes[o + 1].toInt() and 0xFF) shl 8) or
          ((bytes[o + 2].toInt() and 0xFF) shl 16) or
          ((bytes[o + 3].toInt() and 0xFF) shl 24)
      fun i64(o: Int): Long {
        var v = 0L
        for (k in 7 downTo 0) v = (v shl 8) or (bytes[o + k].toLong() and 0xFF)
        return v
      }
      fun f32(o: Int): Float = Float.fromBits(i32(o))
      if (i32(0) == 0) {
        emptyMap()
      } else {
        val result = HashMap<String, Any?>()
        result["position"] =
          Vector3(GodotReal.fromC(f32(4)), GodotReal.fromC(f32(8)), GodotReal.fromC(f32(12)))
        result["normal"] =
          Vector3(GodotReal.fromC(f32(16)), GodotReal.fromC(f32(20)), GodotReal.fromC(f32(24)))
        val colliderHandle = i64(28)
        if (colliderHandle != 0L) result["collider"] = MemorySegment.ofAddress(colliderHandle)
        result["collider_id"] = i64(36)
        result["shape"] = i64(44)
        result
      }
    }
  }

