  // Shared scalar decode for a Variant return delivered through the (out_int, out_double,
  // out_str) triple — by kanama_ios_godot_object_call ([callWithVariantArgs]) and by
  // kanama_ios_godot_ptrcall_ret_variant_scalar ([ptrcallRetVariantScalar], task 100 parcel 2).
  private fun MemScope.decodeVariantScalarReturn(
    retType: Int,
    outInt: LongVar,
    outDouble: DoubleVar,
    outStr: CPointer<ByteVar>,
    strBufSize: Long,
    outStrLen: LongVar,
    outIsRefCounted: IntVar?,
  ): Any? =
    when (retType) {
      VT_BOOL -> outInt.value != 0L
      VT_INT -> outInt.value
      VT_FLOAT -> outDouble.value
      VT_STRING,
      VT_STRING_NAME,
      VT_NODE_PATH -> {
        // StringName/NodePath decode to utf8 in out_str (the C side builds String(from:…));
        // a String surfaces here. NodePath-returning callers re-wrap in NodePath. A value longer
        // than the buffer was parked C-side (kanama_ios_emit_utf8_return): drain it whole.
        val len = outStrLen.value
        when {
          len <= 0L -> ""
          len <= strBufSize -> outStr.readBytes(len.toInt()).decodeToString()
          else -> {
            val full = allocArray<ByteVar>(len)
            val got = kanama_ios_godot_take_pending_utf8(full, len)
            if (got <= 0L) "" else full.readBytes(minOf(got, len).toInt()).decodeToString()
          }
        }
      }
      // A Variant Object return is a GodotObject wrapper (RefCounted when the engine flagged the
      // handle as ref-counted and the caller owns it), the desktop contract. Until task 115 the
      // non-ref-counted case surfaced the raw MemorySegment, so `call("get", "shooter") as?
      // GodotObject` was null on iOS while desktop returned the node.
      VT_OBJECT ->
        if (outInt.value != 0L) {
          val handle = GodotHandle(MemorySegment.ofAddress(outInt.value))
          if (outIsRefCounted != null && outIsRefCounted.value != 0) RefCounted(handle)
          else GodotObject(handle)
        } else {
          null
        }
      // Small fixed-size returns arrive as raw component bytes in out_str (see
      // kanama_ios_godot_object_call); zero length = the C side could not decode.
      VT_VECTOR2 ->
        if (outStrLen.value >= 8L) {
          val b = outStr.readBytes(8)
          Vector2(realLE(b, 0), realLE(b, 4))
        } else null
      VT_VECTOR2I ->
        if (outStrLen.value >= 8L) {
          val b = outStr.readBytes(8)
          Vector2i(i32LE(b, 0), i32LE(b, 4))
        } else null
      VT_VECTOR3 ->
        if (outStrLen.value >= 12L) {
          val b = outStr.readBytes(12)
          Vector3(realLE(b, 0), realLE(b, 4), realLE(b, 8))
        } else null
      VT_COLOR ->
        if (outStrLen.value >= 16L) {
          val b = outStr.readBytes(16)
          Color(
            Float.fromBits(i32LE(b, 0)),
            Float.fromBits(i32LE(b, 4)),
            Float.fromBits(i32LE(b, 8)),
            Float.fromBits(i32LE(b, 12)),
          )
        } else null
      else -> null
    }

  // Generic Variant Object.call dispatch (mirrors desktop ObjectCalls.callWithVariantArgs):
  // boxes each arg into a Variant C-side and invokes [methodBind] via the Variant path,
  // for the varargs / dynamic methods ptrcall can't express (Object.call, set_deferred,
  // set_custom_mouse_cursor). Returns the decoded result — scalar (Boolean/Long/Double/
  // String/object MemorySegment) or small fixed-size (Vector2/Vector2i/Vector3/Color,
  // raw component bytes via out_str) — or null (nil / un-decoded return, e.g. Dictionary/
  // Array/Transform). A String-family return longer than the 1 KiB inline buffer is parked
  // C-side and drained whole (task 100) — the value is captured once, the call is not re-issued.
  // Build the tagged-entry blob consumed by the C shim's PT_ARRAY boxer. Object.set uses this
  // path for List<Enum> values after callers map the enum entries to integer ordinals. Keep this
  // deliberately narrow: other List element families need their own audited Variant encoding.
  private fun MemScope.encodeIntegerArrayArg(values: List<*>): CPointer<ByteVar> {
    val entries =
      values.map { value ->
        when (value) {
          null -> Pair(PT_VOID, null)
          is Int -> Pair(PT_INT64, value.toLong())
          is Long -> Pair(PT_INT64, value)
          else ->
            error(
              "encodeVariantArgs: unsupported List element type " +
                (value::class.simpleName ?: "<anonymous>")
            )
        }
      }
    val byteCount = 4 + entries.sumOf { (_, value) -> 8 + if (value == null) 0 else 8 }
    val blob = allocArray<ByteVar>(byteCount)
    var offset = 0
    fun putInt32(value: Int) {
      for (byteIndex in 0 until 4) {
        blob[offset + byteIndex] = ((value ushr (byteIndex * 8)) and 0xFF).toByte()
      }
      offset += 4
    }
    fun putInt64(value: Long) {
      for (byteIndex in 0 until 8) {
        blob[offset + byteIndex] = ((value ushr (byteIndex * 8)) and 0xFF).toByte()
      }
      offset += 8
    }
    putInt32(entries.size)
    for ((tag, value) in entries) {
      putInt32(tag)
      putInt32(if (value == null) 0 else 8)
      if (value != null) putInt64(value)
    }
    return blob
  }

  // Lay out a List<Any?> into parallel PT-tag + payload-pointer arrays inside the given MemScope.
  // Shared by the Variant Object.call dispatch and the bound-Callable connect/disconnect path.
  private fun MemScope.encodeVariantArgs(
    args: List<Any?>
  ): Triple<CPointer<IntVar>, CPointer<COpaquePointerVar>, Int> {
    val n = args.size
    val tags = allocArray<IntVar>(if (n > 0) n else 1)
    val ptrs = allocArray<COpaquePointerVar>(if (n > 0) n else 1)
    for (i in 0 until n) {
      when (val a = args[i]) {
        null -> {
          tags[i] = PT_VOID
          ptrs[i] = null
        }
        is Boolean -> {
          val c = alloc<ByteVar>()
          c.value = if (a) 1 else 0
          tags[i] = PT_BOOL
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Int -> {
          val c = alloc<LongVar>()
          c.value = a.toLong()
          tags[i] = PT_INT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Long -> {
          val c = alloc<LongVar>()
          c.value = a
          tags[i] = PT_INT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Float -> {
          val c = alloc<DoubleVar>()
          c.value = a.toDouble()
          tags[i] = PT_FLOAT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Double -> {
          val c = alloc<DoubleVar>()
          c.value = a
          tags[i] = PT_FLOAT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is String -> {
          tags[i] = PT_STRING
          ptrs[i] = a.cstr.ptr.reinterpret<CPointed>()
        }
        is Vector2 -> {
          val c = allocArray<GodotRealVar>(2)
          c[0] = GodotReal.toC(a.x)
          c[1] = GodotReal.toC(a.y)
          tags[i] = PT_VECTOR2
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is Vector2i -> {
          val c = allocArray<IntVar>(2)
          c[0] = a.x
          c[1] = a.y
          tags[i] = PT_VECTOR2I
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is Vector3 -> {
          val c = allocArray<GodotRealVar>(3)
          c[0] = GodotReal.toC(a.x)
          c[1] = GodotReal.toC(a.y)
          c[2] = GodotReal.toC(a.z)
          tags[i] = PT_VECTOR3
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is Color -> {
          val c = allocArray<FloatVar>(4)
          c[0] = a.r
          c[1] = a.g
          c[2] = a.b
          c[3] = a.a
          tags[i] = PT_COLOR
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is GodotObject -> {
          val c = alloc<LongVar>()
          c.value = a.segment.address()
          tags[i] = PT_OBJECT
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is MemorySegment -> {
          val c = alloc<LongVar>()
          c.value = a.address()
          tags[i] = PT_OBJECT
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is List<*> -> {
          tags[i] = PT_ARRAY
          ptrs[i] = encodeIntegerArrayArg(a).reinterpret<CPointed>()
        }
        else ->
          error("encodeVariantArgs: unsupported arg type " + (a::class.simpleName ?: "<anonymous>"))
      }
    }
    return Triple(tags, ptrs, n)
  }

